         ecom:orderDate ?orderDate .

  ?item a ecom:OrderItem ;
        ecom:forOrder ?order ;
        ecom:forProduct ?product ;
        ecom:salesAmount ?amount .

  ?product a ecom:Product ;
           ecom:forCategory ?category .

