sparql_query:
PREFIX shop: <http://fictional.ecommerce/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?customerName ?orderDate ?productName ?productPrice ?avgRating ?shippingStatus
WHERE {
  # Customer must be premium
  ?customer a shop:Customer ;
            shop:customerName ?customerName ;
            shop:customerMembershipLevel "Premium"^^xsd:string ;
            shop:placedOrder ?order .

  # Order details
  ?order a shop:Order ;
         shop:orderDate ?orderDate ;
         shop:hasPayment ?payment ;
         shop:hasShipping ?shipping ;
         shop:containsItem ?orderItem .

  # Payment must be completed
  ?payment a shop:Payment ;
           shop:paymentStatus "Completed"^^xsd:string .

  # Shipping status
  ?shipping a shop:Shipping ;
            shop:shippingStatus ?shippingStatus .

  # Only shipped or delivered orders
  FILTER(?shippingStatus = "Shipped"^^xsd:string || ?shippingStatus = "Delivered"^^xsd:string)

  # Order contains items
  ?orderItem a shop:OrderItem ;
             shop:forProduct ?product ;
             shop:itemQuantity ?quantity .

  # Product details
  ?product a shop:Product ;
           shop:productName ?productName ;
           shop:productPrice ?productPrice ;
           shop:inCategory ?category .

  # Category must be Electronics
  ?category a shop:Category ;
            shop:categoryName "Electronics"^^xsd:string .

  # Calculate average rating per product
  {
    SELECT ?product (AVG(?rating) AS ?avgRating)
    WHERE {
      ?product shop:hasReview ?rev .
      ?rev shop:reviewRating ?rating .
    }
    GROUP BY ?product
    HAVING (AVG(?rating) > 4.0)
  }

  # Order must be from last year
  FILTER(?orderDate >= "2024-01-01"^^xsd:date)
}
ORDER BY DESC(?orderDate) ?customerName

